#![doc = include_str ! ("../README.md")]
#![no_std]

/// Number of decimal digits per chunk.
pub const CHUNK_SIZE: u32 = 19;
/// Base value used to separate chunks by mod operator.
pub const CHUNK_BASE: u64 = 10_u64.pow(CHUNK_SIZE);
/// Factor used to compress the number of entries in the lookup table.
pub const COMPRESSION_RATE: u32 = 32;
const ADDITIONAL_BITS: u32 = 272;
/// Number of bits used to left-shift the values in the lookup table.
pub const SHIFT: u32 = ADDITIONAL_BITS + COMPRESSION_RATE;
/// Number of chunks cut from the head of the lookup table.
pub const CHUNK_CUTOFF: u32 = 6;

const N_SEGMENTS: usize = 8200;
const SEGMENT_OFFSET: u32 = 7;

#[inline(always)]
pub fn get_pow10_div_pow2_params(exp: i32) -> (usize, (u32, i32)) {
    debug_assert!(exp <= -((COMPRESSION_RATE * SEGMENT_OFFSET) as i32));
    let segment_idx =
        (-exp as u32 / COMPRESSION_RATE - SEGMENT_OFFSET) as usize;
    (segment_idx, POW10_DIV_POW2_PARAMS[segment_idx])
}

#[inline(always)]
pub fn lookup_pow10_div_pow2(
    segment_idx: usize,
    chunk_idx: usize,
) -> (u128, u128, u128) {
    debug_assert!(segment_idx < N_SEGMENTS);
    let offset = segment_idx * CHUNK_CUTOFF as usize;
    POW10_DIV_POW2_TABLE[offset + chunk_idx]
}

